import itertools, random
from problems import Sat, ThreeSat
from reduce import reduce

def sat_solve(inst):
    m = inst["num_vars"]; clauses = inst["clauses"]
    for bits in itertools.product([False, True], repeat=m):
        ok = True
        for cl in clauses:
            if not any((bits[abs(l)-1] if l > 0 else not bits[abs(l)-1]) for l in cl):
                ok = False; break
        if ok: return True
    return False

def three_solve(inst):
    return sat_solve(inst)  # same semantics

def gen_instances(max_vars=3, max_clauses=3, max_len=4):
    # exhaustive-ish: all clauses over vars 1..m with length 0..max_len
    for m in range(0, max_vars+1):
        lits = [l for v in range(1, m+1) for l in (v, -v)]
        all_clauses = []
        for L in range(0, max_len+1):
            for combo in itertools.combinations_with_replacement(lits, L):
                all_clauses.append(list(combo))
        # sample subsets of clauses
        for r in range(0, max_clauses+1):
            for subset in itertools.combinations(all_clauses, r):
                yield {"num_vars": m, "clauses": [list(c) for c in subset]}

count = 0
bad = 0
for inst in gen_instances():
    Sat.validate(inst)
    r = reduce(inst)
    ThreeSat.validate(r)
    a = sat_solve(inst)
    b = three_solve(r)
    count += 1
    if a != b:
        bad += 1
        print("MISMATCH", inst, "->", r, "src", a, "tgt", b)
        if bad > 20: break
print("checked", count, "bad", bad)
EOF
